query:
query RoomPlanDetailAlt($accommodationId: AccommodationIdScalar!, $roomId: RoomIdScalar!, $planId: PlanIdScalar!, $roomPlanBranchNumber: String, $planBranchNumber: String, $roomBranchNumber: String, $cancelPolicyBranchNumber: String, $mealsInputs: [AccommodationMealHistIdInput!], $planUwanosePointVariation: PlanUwanosePointVariationScalar! = 0, $isIkyu: Boolean!, $currency: Currency!, $isInternationalSite: Boolean!) {
  accommodation(accommodationId: $accommodationId) {
    ...AboutChildrenAccommodation
    ...AboutCancelPolicyAccommodation
    ...AboutLoungeAccommodation
    ...AboutNoteAccommodation
    ...AboutNoticeAccommodation
    ...AboutOptionAccommodation
    ...AboutPaymentAccommodation
    ...AboutPriceAccommodation
    ...AddComparisonListAccommodation
    ...IntroductionRoomAccommodationAttributes
    ...IntroductionRoomAccommodationAmenities
    ...RoomPlanDetailAccommodationBookableDateTime
    ...RoomPlanDetailErrorAccommodation
    ...HeaderAccommodationRoomDetail
    ...IntroductionMealAccommodation
    ...IntroductionPlanAccommodation
    ...IntroductionRoomAccommodation
    ...RoomPlanDetailAccommodationLimitation
    ...RoomPlanDetailAccommodationSettlement
    roomPlan(
      roomId: $roomId
      planId: $planId
      branchNumber: $roomPlanBranchNumber
      planUwanosePointVariation: $planUwanosePointVariation
    ) {
      error
    }
  }
}

fragment AboutChildrenRoomPlanChildAmount on RoomPlanChildAmount {
  __typename
  type
  ... on RoomPlanChildAmountFixed {
    amount
    amountWithCurrency: amount(currency: $currency) @include(if: $isInternationalSite)
  }
  ... on RoomPlanChildAmountRate {
    rate
  }
}

fragment CancelPolicyPlan on Plan {
  cancelPolicy(branchNumber: $cancelPolicyBranchNumber) {
    id
    rules {
      __typename
      ... on CancelPolicyRuleDay {
        day
        hourMinutes
      }
      amount {
        __typename
        ... on CancelPolicyRuleAmountFixed {
          amount
          amountWithCurrency: amount(currency: $currency)
        }
        ... on CancelPolicyRuleAmountRate {
          rate
        }
      }
    }
  }
}

fragment LimitationRoomPlan on RoomPlan {
  room(branchNumber: $roomBranchNumber) {
    capacityMin
    capacityMax
    lying
    lyingUpperLimitPeopleCount
  }
  plan(branchNumber: $planBranchNumber) {
    sale
    minRoomCount
    maxRoomCount
    minLodgingCount
    maxLodgingCount
    uwanosePointVariation
  }
  children {
    children {
      kind
      amount {
        type
      }
    }
  }
}

fragment AboutChildrenAccommodation on Accommodation {
  roomPlan(
    roomId: $roomId
    planId: $planId
    branchNumber: $roomPlanBranchNumber
    planUwanosePointVariation: $planUwanosePointVariation
  ) {
    children {
      children {
        kind
        amount {
          ...AboutChildrenRoomPlanChildAmount
        }
      }
      memo
    }
    room(branchNumber: $roomBranchNumber) {
      lyingUpperLimitPeopleCount
    }
  }
}

fragment AboutCancelPolicyAccommodation on Accommodation {
  roomPlan(
    roomId: $roomId
    planId: $planId
    planUwanosePointVariation: $planUwanosePointVariation
    branchNumber: $roomPlanBranchNumber
  ) {
    plan(branchNumber: $planBranchNumber) {
      ...CancelPolicyPlan
    }
  }
}

fragment AboutLoungeAccommodation on Accommodation {
  loungeServiceContent
  roomPlan(
    roomId: $roomId
    planId: $planId
    branchNumber: $roomPlanBranchNumber
    planUwanosePointVariation: $planUwanosePointVariation
  ) {
    attributes {
      name
    }
  }
}

fragment AboutNoteAccommodation on Accommodation {
  generalNotes
  roomPlan(
    roomId: $roomId
    planId: $planId
    branchNumber: $roomPlanBranchNumber
    planUwanosePointVariation: $planUwanosePointVariation
  ) {
    plan(branchNumber: $planBranchNumber) {
      notes
      uwanosePointVariation
    }
  }
}

fragment AboutNoticeAccommodation on Accommodation {
  notes
}

fragment AboutOptionAccommodation on Accommodation {
  roomPlan(
    roomId: $roomId
    planId: $planId
    branchNumber: $roomPlanBranchNumber
    planUwanosePointVariation: $planUwanosePointVariation
  ) {
    plan(branchNumber: $planBranchNumber) {
      options {
        name
        amount
        amountWithCurrency: amount(currency: $currency) @include(if: $isInternationalSite)
      }
    }
  }
}

fragment AboutPaymentAccommodation on Accommodation {
  roomPlan(
    roomId: $roomId
    planId: $planId
    branchNumber: $roomPlanBranchNumber
    planUwanosePointVariation: $planUwanosePointVariation
  ) {
    plan(branchNumber: $planBranchNumber) {
      cardSettlement
    }
  }
}

fragment AboutPriceAccommodation on Accommodation {
  roomPlan(
    roomId: $roomId
    planId: $planId
    branchNumber: $roomPlanBranchNumber
    planUwanosePointVariation: $planUwanosePointVariation
  ) {
    plan(branchNumber: $planBranchNumber) {
      bathTaxApply
    }
  }
}

fragment AddComparisonListAccommodation on Accommodation {
  roomPlan(
    roomId: $roomId
    planId: $planId
    branchNumber: $roomPlanBranchNumber
    planUwanosePointVariation: $planUwanosePointVariation
  ) {
    inComparisonList
  }
}

fragment IntroductionRoomAccommodationAttributes on Accommodation {
  roomPlan(
    roomId: $roomId
    planId: $planId
    branchNumber: $roomPlanBranchNumber
    planUwanosePointVariation: $planUwanosePointVariation
  ) {
    attributes {
      name
      value
    }
    room(branchNumber: $roomBranchNumber) {
      attributes {
        value
        name
      }
    }
    plan(branchNumber: $planBranchNumber) {
      attributes {
        value
        name
      }
    }
  }
}

fragment IntroductionRoomAccommodationAmenities on Accommodation {
  amenities {
    amenity {
      id
      name
    }
    available
  }
  roomPlan(
    roomId: $roomId
    planId: $planId
    branchNumber: $roomPlanBranchNumber
    planUwanosePointVariation: $planUwanosePointVariation
  ) {
    room(branchNumber: $roomBranchNumber) {
      isAmenitiesDisplay
      amenities {
        amenity {
          id
          name
        }
        available
      }
    }
    plan(branchNumber: $planBranchNumber) {
      amenities {
        amenity {
          id
          name
        }
        available
      }
    }
  }
}

fragment RoomPlanDetailAccommodationBookableDateTime on Accommodation {
  roomPlan(
    roomId: $roomId
    planId: $planId
    branchNumber: $roomPlanBranchNumber
    planUwanosePointVariation: $planUwanosePointVariation
  ) {
    plan(branchNumber: $planBranchNumber) {
      bookableDateTimeFrom
      bookableDateTimeTo
    }
  }
}

fragment RoomPlanDetailErrorAccommodation on Accommodation {
  roomPlan(
    roomId: $roomId
    planId: $planId
    branchNumber: $roomPlanBranchNumber
    planUwanosePointVariation: $planUwanosePointVariation
  ) {
    error
  }
}

fragment HeaderAccommodationRoomDetail on Accommodation {
  roomPlan(
    roomId: $roomId
    planId: $planId
    branchNumber: $roomPlanBranchNumber
    planUwanosePointVariation: $planUwanosePointVariation
  ) {
    room(branchNumber: $roomBranchNumber) {
      attributes {
        value
        name
      }
      capacityMax
      capacityMin
      checkInTimeFrom
      checkInTimeTo
      checkOutTime
      floorPlan
      images(first: 50) {
        url
        alt
      }
      meterFrom
      meterTo
      name
      type {
        code
        name
      }
    }
    plan(branchNumber: $planBranchNumber) {
      bookableEndSoon
      bookableStartSoon
      checkInTimeFrom
      checkInTimeTo
      checkOutTime
      imageUrls(first: 99)
      isIkyuLimit @include(if: $isIkyu)
      limitedTwoWeeks
      memberRank @include(if: $isIkyu)
      name
      planId
      sale
      specialImageUrls(first: 1)
      meal {
        code
        name
      }
      useCheckInOut
    }
  }
}

fragment IntroductionMealAccommodation on Accommodation {
  roomPlan(
    roomId: $roomId
    planId: $planId
    branchNumber: $roomPlanBranchNumber
    planUwanosePointVariation: $planUwanosePointVariation
  ) {
    plan(branchNumber: $planBranchNumber) {
      meals(inputs: $mealsInputs) {
        type
        name
        prText
        place
        menu
        notes
        openAllDay
        startTime
        endTime
        lastOrderTime
        images(first: 10) {
          url
          alt
        }
      }
    }
  }
}

fragment IntroductionPlanAccommodation on Accommodation {
  roomPlan(
    roomId: $roomId
    planId: $planId
    branchNumber: $roomPlanBranchNumber
    planUwanosePointVariation: $planUwanosePointVariation
  ) {
    plan(branchNumber: $planBranchNumber) {
      catchCopy
      content
    }
  }
}

fragment IntroductionRoomAccommodation on Accommodation {
  roomPlan(
    roomId: $roomId
    planId: $planId
    branchNumber: $roomPlanBranchNumber
    planUwanosePointVariation: $planUwanosePointVariation
  ) {
    room(branchNumber: $roomBranchNumber) {
      roomId
      name
      type {
        code
        name
      }
      floorPlan
      meterFrom
      meterTo
      presentationText
      capacityMin
      capacityMax
      floorNumberBottom
      floorNumberTop
      beds {
        count
        width
        height
        length
      }
      images(first: 50) {
        url
        alt
      }
    }
  }
}

fragment RoomPlanDetailAccommodationLimitation on Accommodation {
  roomPlan(
    roomId: $roomId
    planId: $planId
    branchNumber: $roomPlanBranchNumber
    planUwanosePointVariation: $planUwanosePointVariation
  ) {
    ...LimitationRoomPlan
  }
}

fragment RoomPlanDetailAccommodationSettlement on Accommodation {
  allowLocalPoint
  roomPlan(
    roomId: $roomId
    planId: $planId
    branchNumber: $roomPlanBranchNumber
    planUwanosePointVariation: $planUwanosePointVariation
  ) {
    plan(branchNumber: $planBranchNumber) {
      bathTaxApply
      cardSettlement
      uwanosePointVariation
    }
  }
}
